from __future__ import annotations  # Enable postponed annotations for a compact headless plotting script.
from pathlib import Path  # Resolve generated result and image paths portably on GitHub Actions.
import pandas as pd  # Read numerical trajectories and regional theta histories from compact CSV outputs.
import matplotlib.pyplot as plt  # Draw linear-coordinate precision-resource and regional-intensity figures.

ROOT = Path(__file__).resolve().parent  # Anchor all plotting inputs and outputs to the variable-theta experiment directory.
RESULTS_DIR = ROOT / "results"  # Read numerical tables and write final PNG figures in the same compact artifact directory.
HISTORY_PATH = RESULTS_DIR / "history.csv"  # Locate the solved precision-resource trajectory table generated by run.py.
THETA_PATH = RESULTS_DIR / "theta_history.csv"  # Locate the regional hotspot-detection and variable-theta history generated by run.py.
ERROR_OUTPUT = RESULTS_DIR / "error_dof_linear.png"  # Define the requested ordinary linear-axis error-versus-DOF output figure.
THETA_OUTPUT = RESULTS_DIR / "theta_by_region.png"  # Define a separate figure exposing dynamic hotspot refinement intensity by semantic region.

history = pd.read_csv(HISTORY_PATH)  # Load all actual solver states from the completed numerical benchmark.
global_df = history[history["method"] == "global_dorfler"].sort_values("dof").copy()  # Extract and resource-order the conventional global Dörfler trajectory.
semantic_df = history[history["method"] == "semantic_partition_dorfler"].sort_values("dof").copy()  # Extract and resource-order the semantic variable-theta trajectory.

fig_error, ax_error = plt.subplots(figsize=(10.5, 6.2))  # Create one uncluttered linear-coordinate precision-resource figure.
ax_error.plot(global_df["dof"], 100.0 * global_df["qoi_rel_error"], marker="o", linewidth=1.8, label="Global Dörfler")  # Plot every actual global solver state without logarithmic axis transformation.
ax_error.plot(semantic_df["dof"], 100.0 * semantic_df["qoi_rel_error"], marker="s", linewidth=1.8, label="Semantic variable θ + Dörfler")  # Plot every actual semantic variable-theta solver state on the same ordinary coordinates.
ax_error.set_xlabel("DOF (resource)")  # Label the horizontal resource axis.
ax_error.set_ylabel("QoI relative error (%)")  # Label the vertical true-reference relative-error axis in percent.
ax_error.set_title("Region-detected variable θ vs global Dörfler")  # Give the precision-resource chart a concise algorithm-specific title.
ax_error.grid(True, alpha=0.25)  # Add a light Cartesian grid while keeping both axes linear.
ax_error.legend()  # Display the trajectory labels for direct visual comparison.
for _, row in global_df.iterrows():  # Traverse every actual global Dörfler state for adaptive-round annotations.
    ax_error.annotate(f"r{int(row['round'])}", (row["dof"], 100.0 * row["qoi_rel_error"]), xytext=(5, 5), textcoords="offset points", fontsize=8)  # Label the global state with its round index.
for _, row in semantic_df.iterrows():  # Traverse every actual semantic variable-theta state for adaptive-round annotations.
    ax_error.annotate(f"r{int(row['round'])}", (row["dof"], 100.0 * row["qoi_rel_error"]), xytext=(5, -12), textcoords="offset points", fontsize=8)  # Label the semantic state with its round index.
fig_error.tight_layout()  # Adjust margins so all axis labels, annotations, and legend remain visible.
fig_error.savefig(ERROR_OUTPUT, dpi=220, bbox_inches="tight")  # Save the high-resolution linear-axis precision-resource PNG into the Actions artifact directory.
plt.close(fig_error)  # Close the first figure explicitly so the headless runner releases plotting resources.

theta = pd.read_csv(THETA_PATH)  # Load the actual dynamic regional theta values computed from estimator density at every semantic marking round.
fig_theta, ax_theta = plt.subplots(figsize=(10.5, 5.8))  # Create a second independent chart dedicated to hotspot-heavy regional refinement intensity.
ax_theta.plot(theta["round"], theta["hole_theta"], marker="o", linewidth=1.8, label="Hole region θ")  # Plot the through-hole region bulk parameter over adaptive rounds.
ax_theta.plot(theta["round"], theta["root_theta"], marker="s", linewidth=1.8, label="Root region θ")  # Plot the clamped-root region bulk parameter over adaptive rounds.
ax_theta.plot(theta["round"], theta["background_theta"], marker="^", linewidth=1.8, label="Background region θ")  # Plot the residual-background region bulk parameter over adaptive rounds.
ax_theta.axhline(0.50, linestyle="--", linewidth=1.2, label="Global θ = 0.50")  # Show the conventional global Dörfler bulk level as a visual reference rather than a regional constraint.
ax_theta.set_xlabel("Adaptive round")  # Label the horizontal axis by adaptive decision round.
ax_theta.set_ylabel("Regional θ")  # Label the vertical axis by dynamically detected regional refinement intensity.
ax_theta.set_title("Hotspot reinvestment through region-dependent θ")  # State directly what the regional-intensity chart is intended to verify.
ax_theta.set_ylim(0.0, 1.0)  # Display the complete admissible bulk-parameter interval for immediate interpretation.
ax_theta.grid(True, alpha=0.25)  # Add a light Cartesian grid for reading regional intensity changes.
ax_theta.legend()  # Display each semantic region and the conventional global reference level.
fig_theta.tight_layout()  # Adjust margins so labels and legend remain fully visible.
fig_theta.savefig(THETA_OUTPUT, dpi=220, bbox_inches="tight")  # Save the high-resolution dynamic regional-theta PNG into the Actions artifact directory.
plt.close(fig_theta)  # Close the second figure explicitly so the runner exits cleanly.
print(f"[plot] wrote {ERROR_OUTPUT}")  # Record the precision-resource figure path in the workflow log.
print(f"[plot] wrote {THETA_OUTPUT}")  # Record the regional-theta figure path in the workflow log.
